CREATE TABLE public.work_registry (LIKE public.works INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES);
ALTER TABLE public.work_registry ADD COLUMN linked_budget_id uuid REFERENCES public.budgets(id), ADD COLUMN origin text NOT NULL DEFAULT 'orcamento' CHECK(origin IN ('orcamento','direto')), ADD COLUMN work_type text, ADD COLUMN payment_conditions text, ADD COLUMN notes text;
GRANT SELECT,INSERT,UPDATE ON public.work_registry TO authenticated; GRANT ALL ON public.work_registry TO service_role;
ALTER TABLE public.work_registry ENABLE ROW LEVEL SECURITY;
CREATE POLICY registry_read ON public.work_registry FOR SELECT TO authenticated USING(public.can_see_costs(auth.uid()) OR public.has_role(auth.uid(),'equipe'));
CREATE POLICY registry_write ON public.work_registry FOR ALL TO authenticated USING(public.can_see_costs(auth.uid())) WITH CHECK(public.can_see_costs(auth.uid()));
INSERT INTO public.work_registry SELECT w.*,w.budget_id,'orcamento',NULL,NULL,NULL FROM public.works w;
COMMENT ON COLUMN public.work_registry.budget_id IS 'DEPRECATED: legacy identity slot; for direct works equals work id and does not reference a budget. Only linked_budget_id identifies a budget.';
CREATE UNIQUE INDEX registry_budget_unique ON public.work_registry(linked_budget_id) WHERE linked_budget_id IS NOT NULL;
DO $$ DECLARE r record; BEGIN FOR r IN SELECT conrelid::regclass AS rel,conname FROM pg_constraint WHERE contype='f' AND confrelid='public.works'::regclass LOOP EXECUTE format('ALTER TABLE %s DROP CONSTRAINT %I',r.rel,r.conname); EXECUTE format('ALTER TABLE %s ADD CONSTRAINT %I FOREIGN KEY(work_id) REFERENCES public.work_registry(id)',r.rel,r.conname); END LOOP; END $$;
CREATE TABLE public.work_openings (work_id uuid PRIMARY KEY REFERENCES public.work_registry(id),reference_date date NOT NULL,original_value numeric NOT NULL DEFAULT 0 CHECK(original_value>=0),existing_extras numeric NOT NULL DEFAULT 0 CHECK(existing_extras>=0),received numeric NOT NULL DEFAULT 0 CHECK(received>=0),paid numeric NOT NULL DEFAULT 0 CHECK(paid>=0),incurred numeric NOT NULL DEFAULT 0 CHECK(incurred>=0),pending_payable numeric NOT NULL DEFAULT 0 CHECK(pending_payable>=0),progress numeric NOT NULL DEFAULT 0 CHECK(progress BETWEEN 0 AND 100),created_by uuid DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now(), CHECK(received<=original_value+existing_extras));
GRANT SELECT,INSERT ON public.work_openings TO authenticated; GRANT ALL ON public.work_openings TO service_role;
ALTER TABLE public.work_openings ENABLE ROW LEVEL SECURITY;
CREATE POLICY opening_access ON public.work_openings FOR ALL TO authenticated USING(public.can_see_costs(auth.uid())) WITH CHECK(public.can_see_costs(auth.uid()));
CREATE TRIGGER registry_audit BEFORE INSERT OR UPDATE ON public.work_registry FOR EACH ROW EXECUTE FUNCTION public.touch_audit();
CREATE OR REPLACE FUNCTION public.registry_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF new.origin='orcamento' AND (new.linked_budget_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.budgets WHERE id=new.linked_budget_id AND status='aprovado')) THEN RAISE EXCEPTION 'Orçamento aprovado obrigatório para esta origem.'; END IF; IF new.origin='direto' AND new.linked_budget_id IS NOT NULL THEN RAISE EXCEPTION 'Cadastro direto não exige orçamento.'; END IF; IF TG_OP='UPDATE' AND (new.origin<>old.origin OR new.linked_budget_id IS DISTINCT FROM old.linked_budget_id) THEN RAISE EXCEPTION 'Origem preservada.'; END IF; IF new.planned_end<new.planned_start OR new.actual_end<new.actual_start THEN RAISE EXCEPTION 'Término anterior ao início.'; END IF; RETURN new; END $$;
CREATE TRIGGER registry_guard BEFORE INSERT OR UPDATE ON public.work_registry FOR EACH ROW EXECUTE FUNCTION public.registry_guard();
CREATE OR REPLACE FUNCTION public.mirror_legacy_work() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.work_registry(id,budget_id,linked_budget_id,name,client_id,architect_id,address,responsible,planned_start,planned_end,actual_start,actual_end,status,archived,is_pilot) VALUES(new.id,new.budget_id,new.budget_id,new.name,new.client_id,new.architect_id,new.address,new.responsible,new.planned_start,new.planned_end,new.actual_start,new.actual_end,new.status,new.archived,new.is_pilot) ON CONFLICT(id) DO UPDATE SET name=excluded.name,address=excluded.address,responsible=excluded.responsible,planned_start=excluded.planned_start,planned_end=excluded.planned_end,actual_start=excluded.actual_start,actual_end=excluded.actual_end,status=excluded.status,archived=excluded.archived,is_pilot=excluded.is_pilot; RETURN new; END $$;
CREATE TRIGGER aaa_registry_mirror AFTER INSERT OR UPDATE ON public.works FOR EACH ROW EXECUTE FUNCTION public.mirror_legacy_work();
CREATE OR REPLACE FUNCTION public.log_work_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE wid uuid; snapshot jsonb; eid uuid; BEGIN snapshot:=to_jsonb(new); IF tg_table_name IN ('works','work_registry') THEN wid:=new.id; ELSE wid:=(snapshot->>'work_id')::uuid; END IF; eid:=coalesce((snapshot->>'id')::uuid,wid); INSERT INTO public.work_history(work_id,entity,entity_id,before,after) VALUES(wid,tg_table_name,eid,CASE WHEN TG_OP='INSERT' THEN NULL ELSE to_jsonb(old) END,snapshot); RETURN new; END $$;
CREATE TRIGGER registry_history AFTER INSERT OR UPDATE ON public.work_registry FOR EACH ROW EXECUTE FUNCTION public.log_work_change();
CREATE TRIGGER opening_history AFTER INSERT ON public.work_openings FOR EACH ROW EXECUTE FUNCTION public.log_work_change();
CREATE OR REPLACE FUNCTION public.create_direct_work(_request_id uuid,_data jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE ref date; prog numeric; BEGIN IF NOT public.can_see_costs(auth.uid()) THEN RAISE EXCEPTION 'Sem permissão.'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(_request_id::text,0)); IF EXISTS(SELECT 1 FROM public.work_registry WHERE id=_request_id AND origin='direto') THEN RETURN _request_id; END IF; IF nullif(trim(_data->>'name'),'') IS NULL OR nullif(_data->>'client_id','') IS NULL THEN RAISE EXCEPTION 'Informe nome e cliente.'; END IF; ref:=(_data->>'reference_date')::date; prog:=coalesce((_data->>'progress')::numeric,0); INSERT INTO public.work_registry(id,budget_id,origin,name,client_id,address,work_type,responsible,planned_start,planned_end,actual_start,status,payment_conditions,notes,is_pilot) VALUES(_request_id,_request_id,'direto',_data->>'name',(_data->>'client_id')::uuid,_data->>'address',_data->>'work_type',_data->>'responsible',nullif(_data->>'start','')::date,nullif(_data->>'end','')::date,nullif(_data->>'actual_start','')::date,coalesce(nullif(_data->>'status',''),'contratacao'),_data->>'payment_conditions',_data->>'notes',coalesce((_data->>'is_pilot')::boolean,false)); INSERT INTO public.work_openings(work_id,reference_date,original_value,existing_extras,received,paid,incurred,pending_payable,progress) VALUES(_request_id,ref,coalesce((_data->>'original_value')::numeric,0),coalesce((_data->>'existing_extras')::numeric,0),coalesce((_data->>'received')::numeric,0),coalesce((_data->>'paid')::numeric,0),coalesce((_data->>'incurred')::numeric,0),coalesce((_data->>'pending_payable')::numeric,0),prog); INSERT INTO public.work_stages(work_id,name,weight,progress) VALUES(_request_id,'Avanço inicial / etapa geral',100,prog); RETURN _request_id; END $$;
REVOKE ALL ON FUNCTION public.create_direct_work(uuid,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.create_direct_work(uuid,jsonb) TO authenticated;
COMMENT ON TABLE public.works IS 'DEPRECATED for application reads/writes: work_registry is canonical; retained for existing budget conversion compatibility.';